head.b:skin:
/*
 * Men's Fashion Picks India — Minimal Editorial Storefront Theme
 * Custom Palette:
 * - Primary Charcoal: #17211F
 * - Warm Cream: #F5F1E8
 * - Muted Gold: #C6A66B
 * - Pure White: #FFFFFF
 * - Main Text: #222222
 * - Secondary Text: #6B7280
 * - Borders: #E5E7EB
 */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: #F5F1E8;
  color: #222222;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color 0.15s ease, opacity 0.15s ease;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Container */
.mfp-wrap {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 20px;
  width: 100%;
}

/* Announcement Bar */
.mfp-announcement-bar {
  background-color: #17211F;
  color: #F5F1E8;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 8px 16px;
  text-align: center;
  font-weight: 500;
  border-bottom: 1px solid rgba(198, 166, 107, 0.25);
}
.mfp-announcement-bar span {
  color: #C6A66B;
  margin-right: 6px;
}

/* Header */
.mfp-site-header {
  background-color: #FFFFFF;
  border-bottom: 1px solid #E5E7EB;
  position: sticky;
  top: 0;
  z-index: 100;
}
.mfp-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}
.mfp-brand-group {
  display: flex;
  flex-direction: column;
}
.mfp-logo-link {
  font-size: 19px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: #17211F;
  text-transform: uppercase;
}
.mfp-tagline {
  font-size: 11px;
  color: #6B7280;
  letter-spacing: 0.04em;
}

/* Navigation */
.mfp-nav {
  display: flex;
  align-items: center;
  gap: 22px;
}
.mfp-nav-link {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #17211F;
  padding: 6px 0;
  position: relative;
}
.mfp-nav-link:hover, .mfp-nav-link.active {
  color: #C6A66B;
}

/* Search Bar */
.mfp-header-search {
  position: relative;
}
.mfp-search-form {
  display: flex;
  align-items: center;
  background: #F5F1E8;
  border: 1px solid #E5E7EB;
  border-radius: 4px;
  padding: 4px 10px;
}
.mfp-search-input {
  border: none;
  background: transparent;
  outline: none;
  font-size: 13px;
  color: #17211F;
  width: 140px;
  transition: width 0.2s ease;
}
.mfp-search-input:focus {
  width: 190px;
}
.mfp-search-btn {
  background: none;
  border: none;
  cursor: pointer;
  color: #6B7280;
  display: flex;
  align-items: center;
  padding: 2px;
}

/* Category Strip */
.mfp-category-strip {
  background-color: #FFFFFF;
  border-bottom: 1px solid #E5E7EB;
  overflow-x: auto;
  white-space: nowrap;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.mfp-category-strip::-webkit-scrollbar {
  display: none;
}
.mfp-category-strip-inner {
  display: flex;
  gap: 16px;
  padding: 10px 20px;
}
.mfp-cat-chip {
  display: inline-block;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
  padding: 5px 14px;
  border-radius: 30px;
  background-color: #F5F1E8;
  color: #17211F;
  border: 1px solid #E5E7EB;
  transition: all 0.15s ease;
}
.mfp-cat-chip:hover, .mfp-cat-chip.active {
  background-color: #17211F;
  color: #FFFFFF;
  border-color: #17211F;
}

/* Hero Section */
.mfp-hero {
  background-color: #17211F;
  color: #FFFFFF;
  padding: 60px 0;
  margin-bottom: 40px;
  position: relative;
}
.mfp-hero-inner {
  max-width: 800px;
  text-align: center;
  margin: 0 auto;
}
.mfp-hero-eyebrow {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: #C6A66B;
  margin-bottom: 12px;
}
.mfp-hero-title {
  font-size: 38px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.01em;
  margin-bottom: 16px;
  color: #FFFFFF;
}
.mfp-hero-sub {
  font-size: 16px;
  color: #D1D5DB;
  max-width: 600px;
  margin: 0 auto 28px;
  line-height: 1.5;
}
.mfp-hero-cta {
  display: inline-block;
  background-color: #C6A66B;
  color: #17211F;
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 13px 32px;
  border-radius: 3px;
  transition: background-color 0.15s ease, transform 0.15s ease;
}
.mfp-hero-cta:hover {
  background-color: #D6BA85;
  transform: translateY(-1px);
}

/* Section Headers */
.mfp-section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 24px;
  border-bottom: 1px solid #E5E7EB;
  padding-bottom: 12px;
}
.mfp-section-title {
  font-size: 22px;
  font-weight: 700;
  color: #17211F;
  letter-spacing: -0.01em;
}
.mfp-section-subtitle {
  font-size: 13px;
  color: #6B7280;
  margin-top: 2px;
}

/* Shop by Category Grid */
.mfp-category-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
  margin-bottom: 48px;
}
.mfp-category-card {
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 6px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
  text-align: center;
  padding: 16px 12px;
}
.mfp-category-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 20px -5px rgba(23, 33, 31, 0.08);
  border-color: #C6A66B;
}
.mfp-category-icon-wrap {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background-color: #F5F1E8;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 10px;
  color: #C6A66B;
  font-weight: 700;
}
.mfp-category-name {
  font-size: 13px;
  font-weight: 700;
  color: #17211F;
  margin-bottom: 4px;
}
.mfp-category-desc {
  font-size: 11px;
  color: #6B7280;
  line-height: 1.3;
}

/* Product Grid */
.mfp-product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-bottom: 48px;
}
.mfp-product-card {
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 6px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  position: relative;
}
.mfp-product-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 24px -6px rgba(23, 33, 31, 0.1);
  border-color: #D1D5DB;
}
.mfp-card-media {
  position: relative;
  aspect-ratio: 4 / 5;
  background: #E5E7EB;
  overflow: hidden;
}
.mfp-card-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.mfp-product-card:hover .mfp-card-media img {
  transform: scale(1.04);
}
.mfp-card-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  background: rgba(23, 33, 31, 0.88);
  color: #FFFFFF;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: 2px;
  backdrop-filter: blur(4px);
}
.mfp-card-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}
.mfp-card-category {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #C6A66B;
  margin-bottom: 4px;
}
.mfp-card-title {
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  color: #17211F;
  margin-bottom: 8px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  height: 38px;
}
.mfp-card-footer {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 12px;
  border-top: 1px solid #F5F1E8;
}
.mfp-card-price-group {
  display: flex;
  flex-direction: column;
}
.mfp-card-price {
  font-size: 15px;
  font-weight: 700;
  color: #17211F;
}
.mfp-card-retailer {
  font-size: 10px;
  color: #6B7280;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.mfp-card-cta-btn {
  background-color: #17211F;
  color: #FFFFFF;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 8px 14px;
  border-radius: 3px;
  transition: background-color 0.15s ease;
  white-space: nowrap;
}
.mfp-card-cta-btn:hover {
  background-color: #C6A66B;
  color: #17211F;
}

/* ===================================================
   PRODUCT DETAIL PAGE (EXACT PINTEREST MATCH)
   =================================================== */
.mfp-product-detail-view {
  padding: 32px 0 64px;
}
.mfp-breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: #6B7280;
  margin-bottom: 24px;
}
.mfp-breadcrumb a:hover {
  color: #17211F;
  text-decoration: underline;
}
.mfp-breadcrumb-sep {
  color: #C6A66B;
}
.mfp-breadcrumb-curr {
  color: #17211F;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 320px;
}

.mfp-detail-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  padding: 36px;
  margin-bottom: 56px;
}

.mfp-detail-gallery {
  position: relative;
}
.mfp-detail-image-wrap {
  aspect-ratio: 4 / 5;
  background-color: #F5F1E8;
  border-radius: 6px;
  overflow: hidden;
  border: 1px solid #E5E7EB;
}
.mfp-detail-image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.mfp-detail-content {
  display: flex;
  flex-direction: column;
}
.mfp-detail-badge-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}
.mfp-detail-cat-badge {
  background-color: #F5F1E8;
  color: #17211F;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 4px 10px;
  border-radius: 2px;
}
.mfp-detail-retailer-badge {
  background-color: #17211F;
  color: #FFFFFF;
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 2px;
}

.mfp-detail-title {
  font-size: 26px;
  font-weight: 700;
  line-height: 1.3;
  color: #17211F;
  margin-bottom: 16px;
  letter-spacing: -0.01em;
}

.mfp-detail-desc {
  font-size: 15px;
  color: #4B5563;
  line-height: 1.7;
  margin-bottom: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid #E5E7EB;
}

.mfp-detail-price-box {
  background-color: #F5F1E8;
  border: 1px solid #E5E7EB;
  border-radius: 6px;
  padding: 16px;
  margin-bottom: 24px;
}
.mfp-price-row {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 4px;
}
.mfp-price-amount {
  font-size: 24px;
  font-weight: 700;
  color: #17211F;
}
.mfp-price-tag {
  font-size: 12px;
  color: #6B7280;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.mfp-price-disclaimer {
  font-size: 11px;
  color: #6B7280;
  line-height: 1.4;
}

/* Outbound Affiliate CTA */
.mfp-primary-cta {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background-color: #17211F;
  color: #FFFFFF;
  font-size: 14px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 16px 24px;
  border-radius: 4px;
  transition: background-color 0.2s ease, transform 0.15s ease;
  cursor: pointer;
  text-align: center;
  margin-bottom: 16px;
}
.mfp-primary-cta:hover {
  background-color: #C6A66B;
  color: #17211F;
  transform: translateY(-2px);
}
.mfp-primary-cta svg {
  width: 18px;
  height: 18px;
}

/* Transparent Affiliate Disclosure Box */
.mfp-affiliate-disclosure-box {
  font-size: 11px;
  color: #6B7280;
  line-height: 1.5;
  background: #FAFAF9;
  border: 1px dashed #D1D5DB;
  border-radius: 4px;
  padding: 12px 14px;
  margin-bottom: 24px;
}
.mfp-affiliate-disclosure-box strong {
  color: #17211F;
}

/* Secondary Nav */
.mfp-secondary-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 16px;
  border-top: 1px solid #E5E7EB;
  font-size: 13px;
  font-weight: 600;
}
.mfp-secondary-nav a {
  color: #17211F;
  display: flex;
  align-items: center;
  gap: 4px;
}
.mfp-secondary-nav a:hover {
  color: #C6A66B;
}

/* Related Products Section */
.mfp-related-section {
  margin-top: 48px;
}
.mfp-related-header {
  margin-bottom: 24px;
  border-bottom: 1px solid #E5E7EB;
  padding-bottom: 12px;
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}
.mfp-related-title {
  font-size: 20px;
  font-weight: 700;
  color: #17211F;
}
.mfp-related-sub {
  font-size: 13px;
  color: #6B7280;
}

/* Footer */
.mfp-footer {
  background-color: #17211F;
  color: #D1D5DB;
  padding: 56px 0 28px;
  margin-top: auto;
  border-top: 2px solid #C6A66B;
}
.mfp-footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 40px;
}
.mfp-footer-brand h4 {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #FFFFFF;
  margin-bottom: 10px;
}
.mfp-footer-brand p {
  font-size: 13px;
  line-height: 1.6;
  color: #9CA3AF;
  max-width: 360px;
}
.mfp-footer-col h5 {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #C6A66B;
  margin-bottom: 14px;
}
.mfp-footer-col ul {
  list-style: none;
}
.mfp-footer-col li {
  margin-bottom: 8px;
}
.mfp-footer-col a {
  font-size: 13px;
  color: #9CA3AF;
}
.mfp-footer-col a:hover {
  color: #FFFFFF;
  text-decoration: underline;
}

.mfp-footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: 24px;
  text-align: center;
  font-size: 12px;
  color: #6B7280;
  line-height: 1.6;
}
.mfp-footer-bottom a {
  color: #C6A66B;
}

/* Responsive Breakpoints */
@media (max-width: 1024px) {
  .mfp-category-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .mfp-product-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .mfp-detail-layout {
    gap: 32px;
    padding: 24px;
  }
}

@media (max-width: 768px) {
  .mfp-header-inner {
    height: 64px;
  }
  .mfp-nav {
    display: none;
  }
  .mfp-hero {
    padding: 40px 0;
  }
  .mfp-hero-title {
    font-size: 28px;
  }
  .mfp-hero-sub {
    font-size: 14px;
  }
  .mfp-category-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }
  .mfp-product-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
  }
  .mfp-detail-layout {
    grid-template-columns: 1fr;
    padding: 20px;
    gap: 24px;
  }
  .mfp-footer-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }
}

@media (max-width: 480px) {
  .mfp-product-grid {
    grid-template-columns: 1fr;
  }
  .mfp-logo-link {
    font-size: 16px;
  }
}

article.script:
//
(function() {
  var postBody = document.getElementById('mfp-post-body');
  var ctaBtn = document.getElementById('mfp-visit-store-btn');
  var retailerBadge = document.getElementById('mfp-retailer-badge');
  var priceDisplay = document.getElementById('mfp-price-display');

  // Extract affiliate metadata from structured post data attributes
  if (postBody) {
    var card = postBody.querySelector('.affiliate-product-card, [data-affiliate-url]');
    if (card) {
      var affUrl = card.getAttribute('data-affiliate-url') || card.getAttribute('data-url');
      var store = card.getAttribute('data-affiliate-store') || card.getAttribute('data-store') || 'Amazon India';
      var price = card.getAttribute('data-price');

      if (affUrl && ctaBtn) {
        ctaBtn.setAttribute('href', affUrl);
        ctaBtn.setAttribute('data-store', store);
        ctaBtn.querySelector('span').textContent = 'Visit ' + store + ' \u2014 Check Availability';
      }
      if (store && retailerBadge) {
        retailerBadge.textContent = store;
      }
      if (price && priceDisplay) {
        priceDisplay.textContent = price;
      }
    } else {
      // Fallback: look for first outbound link inside body
      var firstLink = postBody.querySelector('a[href^="http"]');
      if (firstLink && ctaBtn) {
        ctaBtn.setAttribute('href', firstLink.getAttribute('href'));
      }
    }
  }

  // Attach GA4 affiliate_click event
  if (ctaBtn) {
    ctaBtn.addEventListener('click', function(e) {
      var destUrl = this.getAttribute('href');
      var title = this.getAttribute('data-title') || document.title;
      var store = this.getAttribute('data-store') || 'External Retailer';

      if (typeof gtag === 'function') {
        gtag('event', 'affiliate_click', {
          'event_category': 'Affiliate',
          'event_label': title,
          'affiliate_store': store,
          'outbound_url': destUrl
        });
      }
    });
  }

  // Dynamic Related Products Fetcher using Blogger JSON Feed
  var currentPostId = '<data:post.id/>';
  var categoryLabel = '<b:if cond="data:post.labels"><data:post.labels.first.name/></b:if>';
  var relatedGrid = document.getElementById('mfp-related-grid');

  if (categoryLabel && relatedGrid) {
    var feedUrl = '/feeds/posts/default/-/' + encodeURIComponent(categoryLabel) + '?alt=json&max-results=5';
    fetch(feedUrl)
      .then(function(res) { return res.json(); })
      .then(function(data) {
        var entries = (data && data.feed && data.feed.entry) ? data.feed.entry : [];
        var html = '';
        var count = 0;

        for (var i = 0; i < entries.length; i++) {
          var entry = entries[i];
          var entryId = entry.id.$t;
          // Exclude current post
          if (entryId.indexOf(currentPostId) !== -1) continue;

          var entryTitle = entry.title.$t;
          var postUrl = '';
          for (var j = 0; j < entry.link.length; j++) {
            if (entry.link[j].rel === 'alternate') {
              postUrl = entry.link[j].href;
              break;
            }
          }
          var thumbUrl = 'https://placehold.co/400x500/17211F/FFFFFF?text=Men%27s+Fashion';
          if (entry.media$thumbnail) {
            thumbUrl = entry.media$thumbnail.url.replace('/s72-c/', '/w500-h600-c/');
          }

          html += '<article class="mfp-product-card">' +
            '<div class="mfp-card-media">' +
              '<a href="' + postUrl + '"><img src="' + thumbUrl + '" alt="' + entryTitle + '" loading="lazy"/></a>' +
              '<span class="mfp-card-badge">' + categoryLabel + '</span>' +
            '</div>' +
            '<div class="mfp-card-body">' +
              '<h4 class="mfp-card-title"><a href="' + postUrl + '">' + entryTitle + '</a></h4>' +
              '<div class="mfp-card-footer">' +
                '<span class="mfp-card-retailer">Curated Pick</span>' +
                '<a class="mfp-card-cta-btn" href="' + postUrl + '">View Pick &rarr;</a>' +
              '</div>' +
            '</div>' +
          '</article>';

          count++;
          if (count >= 4) break;
        }

        if (count > 0) {
          relatedGrid.innerHTML = html;
        } else {
          document.getElementById('mfp-related-products-box').style.display = 'none';
        }
      })
      .catch(function(err) {
        console.log('Related products feed unavailable:', err);
      });
  }
})();
